   {showRepos&&<div className="grid md:grid-cols-2 gap-3 mt-4">{repositories.map(repo=><a key={repo.url} href={repo.url} target="_blank" rel="noreferrer" className="rounded-xl border border-[#293548] bg-[#080d14]/60 p-4 hover:border-cyan-300/30 transition"><div className="font-semibold text-sm">{repo.name}</div><div className="text-[10px] text-cyan-200 mt-1">@{repo.owner}</div><p className="text-xs text-[#8d9bb0] leading-5 mt-2">{repo.description}</p><span className="inline-flex items-center gap-1 text-[11px] text-[#b7c4d6] mt-3">Open repository <ArrowUpRight size={12}/></span></a>)}</div>}
